-- Requested editorial configuration, not traffic, rankings or search-volume data.
CREATE TABLE seo_topic_library (
 topic_key TEXT PRIMARY KEY CHECK (topic_key ~ '^[a-z0-9][a-z0-9-]{0,79}$'),
 theme TEXT NOT NULL CHECK (char_length(theme) BETWEEN 1 AND 80),
 title TEXT NOT NULL UNIQUE CHECK (char_length(title) BETWEEN 1 AND 80),
 keywords TEXT[] NOT NULL CHECK (cardinality(keywords)=6 AND char_length(array_to_string(keywords,' '))<=1000)
);
